const CACHE_NAME = "gys-cache-v67";
const APP_VERSION = "3.8.13";
self.addEventListener("install", (_event) => {
	self.skipWaiting();
});
self.addEventListener("activate", (event) => {
	event.waitUntil(
		caches
			.keys()
			.then((cacheNames) => {
				return Promise.all(
					cacheNames.map((cacheName) => {
						if (cacheName !== CACHE_NAME) {
							return caches.delete(cacheName);
						}
					}),
				);
			})
			.then(() => self.clients.claim()),
	);
});
self.addEventListener("message", (event) => {
	if (event.data && event.data.type === "GET_VERSION") {
		event.source.postMessage({ type: "VERSION", version: APP_VERSION });
	}
	if (event.data && event.data.type === "CLEAR_CACHE") {
		caches
			.keys()
			.then((cacheNames) => {
				return Promise.all(cacheNames.map((name) => caches.delete(name)));
			})
			.then(() => {
				event.source.postMessage({ type: "CACHE_CLEARED" });
			});
	}
});
self.addEventListener("fetch", (event) => {
	if (event.request.method !== "GET") return;
	var url;
	try {
		url = new URL(event.request.url);
	} catch (_) {
		return;
	}
	if (
		url.pathname.includes("/midi/") ||
		url.pathname.includes("/pdf/") ||
		url.pathname.includes("/chord/") ||
		url.pathname.includes("assets-list.json") ||
		url.pathname.includes("assets-lyrics.json") ||
		url.pathname.includes("assets-chord-list.json")
	) {
		event.respondWith(fetch(event.request));
		return;
	}
	var isLocalAppFile =
		url.origin === self.location.origin &&
		(url.pathname.endsWith(".js") ||
			url.pathname.endsWith(".css") ||
			url.pathname.endsWith(".html") ||
			url.pathname === "/" ||
			url.pathname.endsWith("/"));
	if (isLocalAppFile) {
		event.respondWith(
			caches.open(CACHE_NAME).then((cache) =>
				fetch(event.request)
					.then((networkResponse) => {
						if (networkResponse && networkResponse.status === 200) {
							cache.put(event.request, networkResponse.clone());
						}
						return networkResponse;
					})
					.catch(() =>
						caches
							.match(event.request)
							.then((cachedResponse) => cachedResponse || Response.error()),
					),
			),
		);
		return;
	}
	event.respondWith(
		caches.match(event.request).then((cachedResponse) => {
			if (cachedResponse) {
				return cachedResponse;
			}
			return fetch(event.request)
				.then((networkResponse) => {
					if (
						networkResponse &&
						(networkResponse.status === 200 ||
							networkResponse.type === "opaque")
					) {
						var responseToCache = networkResponse.clone();
						caches.open(CACHE_NAME).then((cache) => {
							cache.put(event.request, responseToCache);
						});
					}
					return networkResponse;
				})
				.catch(() => Response.error());
		}),
	);
});
